'Show_Previous_Dues_Line' => '이전 미수금 줄 표시',
'Show_Previous_Dues_Line_Desc' => '이번 판매 이전에 고객이 갚아야 했던 잔액입니다. 0보다 클 때만 인쇄됩니다.',
