'Show_Net_Balance_Line_Desc' => '이전 미수금에 이번 판매의 미결제 잔액을 더한 금액입니다. 이전 미수금이 0보다 클 때만 인쇄됩니다.',

'QZ_Tray_Printer' => 'QZ Tray(이 컴퓨터의 프린터)',
'QZ_Printer_Name_Hint' => 'QZ Tray를 실행 중인 컴퓨터에 표시되는 프린터 이름입니다. 해당 컴퓨터의 기본 프린터를 사용하려면 비워 두세요. ⟳을 클릭하면 프린터를 검색합니다.',
'QZ_Not_Running' => '이 컴퓨터에서 QZ Tray가 실행되고 있지 않습니다. qz.io에서 설치하여 계속 실행해 두고, QZ가 요청하면 이 웹사이트를 허용하세요.',
'Detect_Printers' => '프린터 검색',
'QZ_Download_Cert' => '인증서 다운로드(override.crt)',
'QZ_Setup_Title' => 'QZ Tray 인쇄 설정 방법(라벨을 인쇄하는 각 컴퓨터에서 한 번만)',
'QZ_Step_Install' => '1. 이 컴퓨터에 QZ Tray를 설치하세요 — qz.io에서 무료로 다운로드한 후 실행하여 계속 켜 두세요(Windows에서는 시스템 트레이, macOS에서는 메뉴 막대에 표시됩니다).',
'QZ_Step_Connect' => '2. 라벨 프린터를 USB로 연결하고 운영 체제에 설치되어 있는지 확인하세요(Windows: 설정 > 프린터 및 스캐너 — macOS: 시스템 설정 > 프린터 및 스캐너).',
'QZ_Step_Detect' => '3. 위의 "프린터 이름" 옆에 있는 ⟳ 버튼을 클릭해 이 컴퓨터의 프린터를 검색한 다음 라벨 프린터를 선택하세요. 컴퓨터의 기본 프린터를 사용하려면 필드를 비워 두세요.',
'QZ_Step_Cert' => '4. 권한 팝업 없이 인쇄하려면 아래 인증서를 다운로드하여 QZ Tray 설치 폴더에 override.crt라는 이름으로 복사하세요(Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). 그런 다음 QZ Tray를 종료했다가 다시 시작하세요.',
'QZ_Step_Test' => '5. 아래의 "테스트 라벨 인쇄"를 클릭하세요. QZ Tray가 권한을 요청하면 허용을 클릭하세요 — 인증서가 설치되어 있으면 다시 묻지 않습니다.',
'QZ_Step_Save' => '6. 제출을 클릭해 설정을 저장하세요. 이제 바코드 인쇄 페이지의 라벨이 브라우저 인쇄 대화 상자 없이 이 프린터로 바로 인쇄됩니다.',
'QZ_Setup_Note' => 'QZ Tray는 현재 브라우저를 사용 중인 컴퓨터에서 실행되므로 Stocky가 원격 서버에 호스팅되어 있어도 작동합니다. 라벨을 인쇄하는 모든 컴퓨터에 QZ Tray를 설치해야 합니다.',

