'Calibration_Sent' => '보정이 시작되었습니다 — 프린터가 빈 라벨 몇 장을 공급하여 측정합니다. 멈추면 테스트 인쇄를 실행하세요.',
'Label_Printer_Dpi' => '프린트헤드 해상도',
