'Wholesale_Pricing_By_Quantity_Hint' => '주문 수량이 구간에 도달했을 때의 개당 가격입니다. 상한이 없는 최상위 구간(예: 100개 이상)은 최대값을 비워 두세요. 첫 번째 구간 미만에서는 일반 소매 가격으로 판매됩니다.',
'Wholesale_Pricing_Variants_Hint' => '하나의 가격 구간표가 제품 전체에 적용됩니다: 각 옵션은 해당 품목 줄의 수량이 구간에 도달하면 구간 가격으로 판매됩니다.',
