/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => '주문 가이드',
'Ord_Guide_Intro' => '온라인 스토어에서 접수된 주문이 재고와 장부에 어떻게 반영되는지, 그리고 금액이 실제로 어디에 기록되는지 설명합니다.',
'Ord_Guide_Lifecycle_Title' => '주문 상태',
'Ord_Guide_Lifecycle_Pending' => '검토를 기다리는 새 주문입니다. 대기 중인 주문만 확인하거나 취소할 수 있습니다.',
'Ord_Guide_Lifecycle_Confirmed' => '주문을 수락했습니다. Stocky가 선택한 창고에 판매를 생성하고 재고를 차감합니다 — 이 판매가 재고, 결제 및 이익 보고서가 참조하는 기록입니다.',
'Ord_Guide_Lifecycle_Shipped' => '주문을 발송했습니다. 이행 단계일 뿐이며, 재고는 확인 시 이미 차감되었습니다.',
'Ord_Guide_Lifecycle_Delivered' => '고객이 주문을 받았습니다. 이때부터 반품 기간이 시작됩니다.',
'Ord_Guide_Lifecycle_Cancelled' => '주문이 확인 전에 취소되어 판매가 생성되지 않았고 재고도 차감되지 않았습니다.',
'Ord_Guide_PaymentStatus_Tip' => '결제 시 설정되며 여기서는 편집할 수 없습니다. 결제를 기록하는 방법을 보려면 클릭하세요.',
'Ord_Guide_Payment_Title' => '결제 상태',
'Ord_Guide_Payment_Intro' => '이 열은 고객이 결제 시 선택한 결제 방식을 기록합니다. 스토어프런트에서 설정되며 이 페이지에서 편집할 수 없습니다 — 실제 금액은 주문 확인 시 생성되는 판매에서 관리됩니다.',
'Ord_Guide_Payment_Paid' => '고객이 결제 게이트웨이를 통해 이미 온라인으로 결제했습니다. 주문을 확인하면 판매가 결제 완료 상태로 생성되고 결제도 자동으로 기록됩니다 — 추가로 할 일은 없습니다.',
'Ord_Guide_Payment_Pending' => '착불, 계좌 이체 또는 기타 후불 결제 방식입니다. 주문을 확인하면 판매가 미결제 상태로 생성되므로, 대금을 받은 후 직접 기록해야 합니다 — 아래 단계를 참고하세요.',
'Ord_Guide_Payment_Failed' => '게이트웨이가 결제를 거절했거나 고객이 결제를 중단했습니다. 주문은 자동으로 취소됩니다.',
'Ord_Guide_MarkPaid_Title' => '결제를 대기에서 결제 완료로 변경하기',
'Ord_Guide_MarkPaid_Step1' => '먼저 여기서 주문을 확인하세요 — 확인해야 판매가 생성됩니다.',
'Ord_Guide_MarkPaid_Step2' => '판매 > 모든 판매를 열어 해당 판매를 찾으세요(같은 고객이며, 상세 페이지에 원본 온라인 주문이 표시됩니다).',
'Ord_Guide_MarkPaid_Step3' => '행 작업 메뉴를 열고 결제 생성을 선택하세요.',
'Ord_Guide_MarkPaid_Step4' => '금액, 결제 수단 및 날짜를 입력한 후 저장하세요. 금액에 따라 판매가 자동으로 부분 결제 또는 결제 완료로 변경됩니다.',
'Ord_Guide_MarkPaid_Note' => '여기 표시되는 결제 상태는 결제 시 선택한 내용을 계속 기록하며 그대로 유지됩니다. 판매가 회계 기록이며 결제 및 이익 보고서에 반영됩니다. 입력한 내용을 검토하거나 편집하려면 판매에서 결제 보기를 사용하세요.',
'Ord_Guide_Notes_Title' => '참고 사항',
'Ord_Guide_Note_Warehouse' => '확인 시 선택한 창고에서 재고가 차감됩니다. 주문 전체를 충당할 수 없는 창고는 목록에 재고 없음으로 표시됩니다.',
'Ord_Guide_Note_Preorder' => '예약 주문 품목은 재고 확인을 건너뛰므로, 해당 품목이 포함된 주문은 아직 수량이 없어도 확인할 수 있습니다.',
'Ord_Guide_Note_Flagged' => '플래그 태그는 결제 시 주문이 사기 검사에 걸렸다는 뜻입니다. 태그에 마우스를 올려 사유를 확인하고 확인 전에 주문을 검토하세요.',
'Ord_Guide_Note_Cancel' => '주문이 대기 중일 때만 취소할 수 있습니다. 확인된 후에는 판매 또는 고객 반품을 통해 되돌리세요.',


