'Upd_Not' => '없습니다',
'Upd_Guide_Code_Overwritten' => '애플리케이션 코드를 수동으로 수정한 경우 업데이트로 인해 변경 사항이 덮어쓰기됩니다. 데이터, 업로드 파일, 설정 및 .env는 항상 보존됩니다.',
'Upd_Guide_Running_Title' => '2. 업데이트 실행',
'Upd_Guide_Run_Open' => '{path}(이 페이지)을(를) 열고 {tab} 탭에 머무르세요.',
'Upd_Guide_Run_Upload' => '{upload}: 다운로드한 패키지를 업로드 상자에 클릭하거나 끌어 놓으세요. 큰 파일은 작은 조각으로 나누어 업로드되므로 업로드 제한이 낮은 공유 호스팅에서도 작동합니다. 체크섬이 손상되거나 불완전한 업로드를 방지합니다.',
'Upd_Upload_The_Zip' => 'ZIP 업로드',
'Upd_Guide_Run_Validation' => '업로드 후 {auto} ({button} 버튼으로 다시 실행할 수 있습니다). 시스템은 ZIP 무결성, 패키지 구조 및 완전성, 버전 호환성(다운그레이드는 거부됨), 필수 PHP 버전 및 확장, 파일 권한, 여유 디스크 공간, 데이터베이스 연결, 구성, 그리고 다른 업데이트가 실행 중이지 않은지를 확인합니다.',
'Upd_Validation_Runs_Automatically' => '검증이 자동으로 실행됩니다',
'Upd_Guide_Run_Review' => '{panel} 패널을 검토하세요. {button} 버튼은 모든 중요 점검을 통과해야만 나타납니다. 점검에 실패하면 메시지에 무엇을 수정해야 하는지 정확히 표시됩니다.',
'Upd_Guide_Run_Click' => '{button}을(를) 클릭하고 확인하세요. 그런 다음 {keep} 진행 표시줄을 지켜보세요. 시스템은 다음 순서로 작업을 수행합니다:',
'Upd_Keep_Page_Open' => '이 페이지를 열어 둔 채',
'Upd_Guide_Phase_Backup' => '{label} — 전체 데이터베이스 덤프, 업데이트로 변경될 수 있는 모든 애플리케이션 파일의 ZIP, 그리고 {env}의 사본이 생성되고 {verified}됩니다. 업로드 파일({images})과 {storage}은(는) 업데이트로 변경되지 않으므로 보관되지 않습니다. 백업을 생성할 수 없으면 업데이트가 여기서 중단되며 아무것도 변경되지 않습니다.',
'Upd_Verified' => '검증',
'Upd_Guide_Phase_Prepare' => '{label} — 새 버전이 스테이징 영역에 압축 해제되고 다시 검증됩니다. 운영 중인 애플리케이션은 아직 변경되지 않습니다.',
'Upd_Guide_Phase_Maintenance' => '{label} — 유지 보수 모드가 활성화되며, 방문자에게는 "곧 돌아오겠습니다" 화면이 표시됩니다.',
'Upd_Guide_Phase_Files' => '{label} — 새 파일이 거의 즉시 교체되며, 이전 파일은 롤백을 위해 따로 보관됩니다. 보호된 경로({env}, {storage}, {images})는 절대 교체되지 않습니다.',
'Upd_Guide_Phase_Database' => '{label} — 마이그레이션이 실행된 후 권한, 번역 및 템플릿이 갱신됩니다.',
'Upd_Guide_Phase_Cache' => '{label} — 모든 캐시가 지워지고 다시 생성됩니다.',
'Upd_Guide_Phase_Verify' => '{label} — 상태 점검을 통해 새 버전이 정상적으로 부팅되는지, 데이터베이스가 작동하는지, 모든 마이그레이션이 실행되었는지, 구성이 유효한지 확인합니다.',
'Upd_Guide_Phase_Done' => '{label} — 유지 보수 모드가 해제되고 임시 파일이 정리됩니다.',
'Upd_Guide_Run_Success' => '{success}이(가) 표시되면 {reload}을(를) 클릭하고 브라우저를 강력 새로 고침({keys})하여 새 관리자 패널 자산을 불러오세요.',
'Upd_Update_Successful_Short' => '업데이트 성공',
'Upd_Guide_No_Internet' => '업데이트 중에는 인터넷 연결이 필요하지 않습니다. 모든 것은 업로드한 ZIP에서 가져옵니다. 연결이 끊기거나 브라우저를 닫아도 업데이트가 중단되지 않습니다. 서버가 멈춘 지점을 정확히 기억합니다.',
'Upd_Guide_Wrong_Title' => '3. 문제가 발생한 경우',
'Upd_Guide_Wrong_Rollback' => '{label} — 파일 변경이 시작된 후 문제가 발생하면(압축 해제 오류, 마이그레이션 실패, 상태 점검 실패, 디스크 공간 부족 등) 시스템이 검증된 백업에서 이전 파일과 데이터베이스를 자동으로 복원하고, 유지 보수 모드를 해제한 다음 {message}을(를) 보고합니다. 정확히 시작했던 상태로 돌아갑니다.',
'Upd_Automatic_Rollback' => '자동 롤백',
'Upd_Failed_Previous_Restored' => '업데이트 실패 — 이전 버전이 복원되었습니다',
'Upd_Guide_Wrong_Interrupted' => '{label}(서버 재시작, 시간 초과, 브라우저 닫힘, 정전) — 이 페이지를 다시 열면 빨간색 배너에 두 가지 안전한 선택지가 표시됩니다: {resume}(멈춘 단계부터 정확히 재개) 또는 {rollback}(백업에서 이전 버전 복원).',
'Upd_Interrupted_Update' => '중단된 업데이트',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path}에 있는 독립형 {console}을(를) 사용하세요. 사이트가 유지 보수 모드이거나 관리자 패널 자산이 손상된 경우에도 작동하며, 동일한 계속 / 롤백 작업을 제공합니다. 유지 보수 화면 하단에도 눈에 띄지 않는 "관리자 접근" 링크가 있습니다.',
'Upd_Admin_Unreachable' => '관리자 패널에 접근할 수 없음',
'Upd_Recovery_Console' => '복구 콘솔',
'Upd_Guide_Wrong_Locked_Out' => '{label} — 업데이트가 실행되는 동안 이 페이지에 {link}가 표시됩니다. 다시 들어와야 할 경우(예: 세션이 만료된 후)를 대비해 저장해 두세요. 이 링크로 유지 보수 화면을 통과하여 다시 로그인할 수 있습니다.',
'Upd_Locked_Out_Maintenance' => '유지 보수 모드로 인해 접근 불가',
'Upd_Bypass_Link' => '우회 링크',
'Upd_Guide_Wrong_Concurrent' => '{label} — 해당 관리자에게는 {message} 메시지가 표시됩니다. 한 번에 하나의 업데이트만 실행할 수 있습니다.',
'Upd_Another_Admin_Updating' => '다른 관리자가 동시에 업데이트를 시도하는 경우',
'Upd_Guide_Backups_Title' => '4. 백업 및 복원',
'Upd_Guide_Backups_Created' => '모든 업데이트는 어떤 것도 변경하기 {before} 백업을 생성합니다: 업데이트로 교체될 수 있는 모든 애플리케이션 파일, {env}의 사본, 그리고 전체 데이터베이스 덤프입니다. 업로드 파일과 {storage}은(는) 업데이트로 수정되지 않으므로 백업에 포함되지 않습니다 — 이들은 직접 백업해 두세요. 백업은 {path}에 저장되며 웹에서 절대 접근할 수 없습니다.',
'Upd_Before' => '전에',
'Upd_Guide_Backups_Panel' => '{tab} 탭의 {panel} 패널에 날짜, 버전 및 크기와 함께 백업이 나열됩니다. 여기에서 완전한 백업을 {restore}하거나(파일 + 데이터베이스 — 현재 데이터베이스의 안전 사본을 먼저 만듭니다) 오래된 백업을 {delete}할 수 있습니다.',
'Upd_Restore_Verb' => '복원',
'Upd_Delete_Verb' => '삭제',
'Upd_Guide_Backups_Retention' => '{keep}을(를) 사용하여 보관할 백업 수를 선택하세요. 업데이트가 성공할 때마다 오래된 백업은 자동으로 제거됩니다. 남아 있는 유일한 완전한 백업은 삭제할 수 없으므로 항상 되돌릴 방법이 있습니다.',
'Upd_Guide_Manual_Title' => '5. 수동 업데이트 (대체 방법)',
'Upd_Guide_Manual_Text' => '직접 업데이트하는 것을 선호하거나 서버에서 업로더를 사용할 수 없는 경우 이 페이지의 {tab} 탭에 있는 단계별 지침을 따르세요.',
'Upd_Guide_Clear_Cache_First' => '업데이트 후 페이지가 깨지거나 비어 보이면 먼저 브라우저 캐시를 지우세요. 거의 항상 그것이 원인입니다.',
'Upd_Restore_Backup_Confirm' => '이 백업을 복원하시겠습니까? 현재 파일과 현재 데이터베이스가 백업으로 교체됩니다. 현재 데이터베이스의 안전 사본을 먼저 만듭니다. (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce 쇼핑몰이 ERP와 동기화 상태를 유지하는 방법입니다. 아래 cron 줄은 이 서버에 맞게 작성되었으므로 그대로 복사하여 사용할 수 있습니다.',
'Woo_Guide_Ways_Note' => 'Shopify와 달리 WooCommerce는 스스로 ERP에 아무것도 보내지 않습니다. 여기에는 웹훅 수신기가 없으므로 ERP로 {in} 모든 데이터는 일정에 따라 도착합니다. {out} 재고만 즉시 반영될 수 있습니다.',
'Woo_In' => '들어오는',
'Woo_Out' => '나가는',
'Woo_Guide_Both_Ways_Title' => '양방향 모두 먼저 필요한 사항',
'Woo_Api_Keys' => 'API 키',
'Woo_Guide_Api_Keys_Text' => '{path}, 권한 {perm}. 컨슈머 키와 시크릿을 스토어 URL과 함께 {settings} 탭에 복사하세요. 스토어 URL은 끝에 슬래시가 없는 사이트 주소입니다 (예: {example}).',
'Woo_Credentials_Saved' => '자격 증명 저장됨',
'Woo_Not_Configured_Yet' => '아직 구성되지 않음',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress 애플리케이션 비밀번호 (선택 사항)',
'Woo_Guide_Wp_App_Password_Text' => '제품 이미지에만 사용됩니다. WooCommerce API는 제품, 재고, 카테고리, 브랜드, 고객 및 주문을 전송하고, WordPress API는 미디어 라이브러리를 검색하고 아직 없는 이미지를 업로드합니다.',
'Woo_Guide_Wp_App_Password_Note' => '미디어를 관리할 수 있는 WordPress 사용자를 사용하고 {path}에서 비밀번호를 만드세요. 두 필드를 모두 비워 두어도 모든 항목이 동기화되며, 이미지 첨부만 건너뜁니다.',
'Woo_Guide_Pick_Way_Title' => '그다음 동기화 방식을 선택하세요',
'Woo_Right_Away' => '즉시',
'Woo_Stock_Live' => '재고 실시간',
'Woo_Stock_Not_Live' => '재고 실시간 아님',
'Woo_Guide_Realtime_Lead' => '한 방향만 해당됩니다: ERP에서 나가는 재고와 제품. WooCommerce에서 발생한 주문과 제품 수정은 여전히 일정에 따라 도착합니다 — 다른 탭을 참조하세요.',
'Woo_Push_Stock_On_Change' => '재고가 변경되는 즉시 전송',
'Woo_Setting_People_Miss' => '많은 사람들이 놓치는 설정입니다',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS 판매는 WooCommerce에 자동으로 {not}. 이 설정을 끄면 쇼핑몰은 다음 재고 동기화(기본값 1시간) 때에야 알게 되며, 그 사이에 이미 계산대에서 판매한 상품을 판매할 수 있습니다.',
'Woo_Does_Not' => '전달되지 않습니다',
'Woo_Guide_Tick_Instant' => '{settings} 탭에서 {option}을(를) 선택하세요. 설정은 이것으로 끝입니다 — 작업자도, cron도 필요 없습니다. 이후 모든 판매, 반품, 재고 조정, 재고 이동 및 입고된 구매는 저장 직후 해당 제품만 전송하며, 20줄짜리 판매도 전송은 20번이 아닌 한 번입니다. 계산대는 이를 기다리지 않습니다.',
'Woo_Currently' => '현재:',
'Woo_Instant_On_Text' => '켜짐 — 변경 시 재고 전송',
'Woo_Instant_Off_Text' => '꺼짐 — 일정에 따라서만 재고 전송',
'Woo_Guide_Instant_Note' => 'WooCommerce에 이미 연결된 제품만 전송됩니다. 한 번도 동기화되지 않은 제품은 쇼핑몰에서 수정할 대상이 없습니다. 가변 제품은 상위 제품을 통해 전송되며, 콤보 제품은 구성 요소 중 하나라도 변경되면 다시 전송됩니다. 대량 작업(제품 삭제, 창고 초기화)은 이벤트 없이 재고를 기록하므로 시간별 재고 동기화도 유지하는 것이 좋습니다.',
'Woo_Push_Products_On_Save' => '제품이 저장되는 즉시 전송',
'Woo_Guide_Tick_Auto_Products' => '{settings} 탭에서 {option}을(를) 선택하면 Stocky에서 생성, 편집 또는 복제된 제품이 저장 직후 WooCommerce로 전송됩니다 — 세부 정보, 가격, 옵션 및 이미지, 그다음 재고. 새 제품은 야간 제품 동기화를 기다리지 않고 즉시 쇼핑몰에 생성됩니다.',
'Woo_On' => '켜짐',
'Woo_Off' => '꺼짐',
'Woo_Guide_Bulk_Imports_Note' => '대량 가져오기는 하나씩 전송되지 않습니다 — 가져온 후 제품 동기화를 실행하세요. 전송된 제품이 올바른 카테고리에 들어가도록 카테고리와 브랜드를 먼저 동기화하세요.',
'Woo_Nothing_Else_To_Install' => '추가로 설치할 것이 없습니다',
'Woo_Guide_Same_Process' => '대기열 작업자도, cron 항목도 필요 없습니다. 전송은 판매를 처리한 동일한 프로세스에서 응답이 반환된 {after} 실행되므로 계산대가 WooCommerce를 기다리는 일이 없습니다. 전송은 겹치지 않습니다: 전송이 실행되는 동안 발생한 변경 사항은 대기했다가 직후에 전송됩니다.',
'Woo_After' => '후에',
'Woo_Guide_Shop_Stops_Answering' => '응답하지 않는 쇼핑몰은 8초 후 포기하며, 모든 판매가 다시 기다리지 않도록 전송이 5분간 일시 중지됩니다. 그동안 발생한 변경 사항은 일시 중지 후 첫 전송과 함께 나가며, 시간별 재고 동기화가 어쨌든 따라잡습니다. 각 일시 중지는 로그 탭에 기록됩니다.',
'Woo_Guide_Artisan_Exception' => '한 가지 예외: artisan 명령으로 인한 재고 변경은 뒤따를 응답이 없으므로 대신 {queue}에 대기열로 들어갑니다. 이 변경 사항도 신속하게 전송하려면 해당 대기열을 처리하세요:',
'Woo_Cron_Line_Copied' => 'cron 줄이 복사되었습니다',
'Woo_Command_Copied' => '명령이 복사되었습니다',
'Woo_Guide_Not_Woo_Queue' => '의도적으로 {queue} 대기열을 사용하지 않습니다: 그 대기열은 몇 시간이 걸리는 카탈로그 배치를 처리하므로 그 뒤에 대기하는 즉시 전송은 즉시가 아니게 됩니다.',
'Woo_On_A_Schedule' => '일정에 따라',
'Woo_Guide_Scheduled_Lead' => '모든 항목이 주기적으로 양방향으로 다시 확인됩니다. 이를 통해 주문이 ERP에 도착하고, 카탈로그가 게시되며, 빠른 경로에서 놓친 것을 보완합니다. 각 작업에는 자체 cron 항목이 있으므로 원하는 작업만 실행할 수 있습니다.',
'Woo_Guide_Sync_Drains_Queue' => '{command}은(는) 실행되는 동안 자체 대기열을 처리하므로 이 줄들에는 별도의 작업자가 필요하지 않습니다. Windows에서는 작업 스케줄러에서 프로그램 {program}과(와) 동일한 인수를 사용하고 시작 위치를 {path}(으)로 지정하세요.',
'Woo_Or_No_Cron' => '또는 cron 없이',
'Woo_Guide_No_Cron_Text' => '여기의 모든 탭은 필요할 때 동기화되며, 수동 동기화는 페이지가 열려 있는 동안 자체 배치를 처리합니다. 따라서 작은 쇼핑몰은 cron 항목 없이도 운영할 수 있습니다. 대신 아무도 보고 있지 않을 때 발생하는 일은 처리되지 않습니다: 주문은 누군가 버튼을 눌러야만 도착합니다.',
'Woo_Commands_Worth_Knowing' => '알아 두면 유용한 명령',
'Woo_Worth_Knowing' => '알아 둘 사항',
'Woo_Guide_Changing_Url_Clears' => '스토어 URL이나 API 키를 변경하면 모든 매핑이 지워집니다 — 제품, 카테고리, 브랜드 및 고객이 모두 새 스토어로 다시 동기화됩니다.',
'Woo_Guide_Keep_Skus' => 'Stocky와 WooCommerce 간 SKU를 일관되게 유지하세요: 이것이 중복을 막고 안전한 재연결을 가능하게 합니다.',
'Woo_Guide_Stock_Total' => 'Woo에 게시되는 재고는 한 창고의 수치가 아니라 {total}입니다.',
'Woo_Total_Across_Warehouses' => '모든 창고의 합계',
'Woo_Guide_Full_Reference' => '모든 범위, 대기열 동작 방식 및 문제 해결 목록을 포함한 전체 참조는 {file}에 있습니다.',
'Woo_Way_Covers' => '대상',
'Woo_Way_Covers_Realtime' => 'ERP에서 나가는 재고만 — POS 판매, 반품, 재고 조정, 입고된 구매',
'Woo_Way_Covers_Scheduled' => '양방향 전체: 주문 및 제품 변경 수신, 카탈로그 및 재고 송신',
'Woo_Way_Speed' => '속도',
'Woo_Way_Seconds' => '초 단위',
'Woo_Way_Speed_Scheduled' => 'cron 항목에 설정한 대로 (재고는 매시간, 주문은 15분마다)',
'Woo_Way_Needs' => '필요 사항',
