'Salla_Guide_3' => '앱 설정에서 연결 탭에 표시된 OAuth 콜백 URL을 설정하세요.',
'Salla_Guide_4' => '앱의 웹훅 페이지에서 {signature} 보안 방식을 선택하고, 해당 시크릿을 여기의 웹훅 시크릿 필드에 복사하고, 연결 탭에 표시된 웹훅 URL을 설정한 다음 최소한 {e1}, {e2}, {e3}, {e4}, {e5} 및 {e6}을(를) 구독하세요.',
'Salla_Guide_5' => '{connect}을(를) 클릭하고 스토어에서 앱을 승인하세요. (Easy Mode 앱은 대신 {webhook} 웹훅을 통해 자동으로 연결됩니다.)',
'Salla_Guide_6' => '제품을 가져오거나 전송한 다음 재고를 전송하세요. 새 주문은 자동으로 도착하며 {ref}와(과) 같은 참조 번호로 판매 아래에 표시됩니다.',
'Salla_Identity_Sku_Title' => '제품 식별 기준은 SKU입니다',
'Salla_Identity_Sku_Desc' => 'Stocky의 제품 코드는 Salla의 SKU와 매칭됩니다. 양쪽의 SKU를 일관되게 유지하세요. 옵션 제품은 가져오기와 주문에서 매칭되지만 이 버전에서는 전송되지 않습니다.',
'Salla_Connected_To' => '{name}에 연결됨',
