'Salla_Removed_Links' => '연결 {n}개 제거됨',
'Salla_Store_Connected' => 'Salla 스토어가 연결되었습니다.',
'Presta_Not_Configured' => '구성되지 않음',
'Presta_Hero_Desc' => '웹서비스 API를 통해 PrestaShop 스토어와 제품, 재고 및 주문을 동기화합니다.',
'Presta_Webservice_Key' => '웹서비스 키',
'Presta_Saved_Paste_New_Key' => '저장됨 — 교체하려면 새 키를 붙여 넣으세요',
'Presta_From_Menu' => '{menu}에서 확인',
'Presta_Webservice_Key_Help' => 'PrestaShop에서 웹서비스를 활성화하고({menu}), products, stock_availables, orders 및 customers에 대한 권한이 있는 키를 만들어 여기에 붙여 넣으세요. 쓰기 전용으로 저장됩니다.',
'Presta_Shop_Language_Id' => '쇼핑몰 언어 ID',
