'Presta_Push_Products_Desc' => 'PrestaShop에 없는 단순 제품을 (현재 재고와 함께) 생성합니다. 이미 연결된 제품과 옵션 제품은 건너뜁니다 — 제품 세부 정보는 PrestaShop에서 계속 편집하거나, 가져오기로 로컬 사본을 새로 고치세요.',
'Presta_Pull_Products_Desc' => 'PrestaShop 제품을 가져와 기존 제품은 참조(SKU)로 매칭하고 나머지는 새로 생성합니다. 조합은 상위 제품으로 가져옵니다.',
'Presta_Reset_Product_Confirm' => '제품 연결을 초기화하시겠습니까? 주문 내역의 연결은 유지됩니다.',
'Presta_Push_Stock_Desc' => '연결된 모든 제품의 쇼핑몰 재고(stock_availables)를 업데이트합니다.',
'Presta_Pull_Orders_Desc' => '쇼핑몰 주문을 판매로 가져옵니다({ref}와(과) 같은 참조 번호), 최신순. 이미 가져온 주문과 취소된 주문은 건너뛰므로 정기적으로 가져와도 안전합니다. PrestaShop에는 웹훅이 없으므로 바쁜 기간 후에 실행하세요.',
'Presta_Guide_1' => 'PrestaShop 백오피스에서 {menu}을(를) 열고 웹서비스를 활성화하세요.',
'Presta_Guide_2' => '새 키를 추가하고 {products} 및 {stock}에는 {rw} 권한을, {orders} 및 {customers}에는 {view} 권한을 부여하세요.',
'Presta_Guide_3' => '연결 탭에 스토어 URL과 키를 붙여 넣고 저장한 다음 {test}을(를) 실행하세요.',
'Presta_Guide_4' => '쇼핑몰에 이미 카탈로그가 있다면 먼저 제품을 가져오세요(참조/SKU로 매칭). 없는 단순 제품을 생성하려면 전송하세요.',
'Presta_Guide_5' => '수량이 변경될 때마다 재고를 전송하고 주문을 정기적으로 가져오세요 — PrestaShop에는 웹훅이 없으므로 주문은 가져올 때만 도착합니다.',
'Presta_Identity_Title' => '제품 식별 기준은 참조(SKU)입니다',
'Presta_Identity_Desc' => 'Stocky의 제품 코드는 PrestaShop의 참조와 매칭됩니다. 양쪽의 참조를 일관되게 유지하세요. 조합(옵션)은 주문에서 참조로 매칭되지만 이 버전에서는 전송되지 않습니다.',
'Xero_Hero_Title' => 'Xero 회계 동기화',
'Xero_Hero_Desc' => '고객을 Xero 연락처로, 판매를 인보이스로 전송합니다 — 은행 계좌가 구성된 경우 결제도 함께 전송됩니다.',
