'Xero_Push_Invoices_Desc' => '판매마다 AUTHORISED 인보이스를 하나씩 생성합니다(인보이스 번호 = 판매 참조 번호). 판매 품목과 배송, 할인, 세금 라인을 포함하므로 Xero 합계가 판매 합계와 일치합니다. 이미 Xero에 있는 판매는 건너뛰며, 인보이스는 절대 수정되지 않습니다. 없는 연락처는 즉시 생성됩니다.',
