'Xero_Guide_6' => '고객을 먼저 전송한 다음 인보이스를 전송하세요. 인보이스 번호는 판매 참조 번호이므로 연결을 초기화하더라도 Xero에서 중복을 거부합니다.',
'Xero_Amounts_Title' => '금액은 세금 포함 그대로 전송됩니다',
'Xero_Amounts_Desc' => '인보이스는 판매를 정확히 반영하는 NoTax 라인(품목 + 배송 − 할인 + 세금)을 사용하므로 Xero 합계는 항상 Stocky 합계와 같습니다. 회계 담당자가 Xero 안에서 세금 및 배송 라인을 적절한 계정과목으로 다시 매핑할 수 있습니다.',
