'Jumia_Hero_Desc' => 'Jumia Seller Center 리스팅에 가격과 재고를 전송하고 마켓플레이스 주문을 판매로 가져옵니다.',
'Jumia_Api_Url_Label' => 'API URL (해당 국가의 Seller Center 엔드포인트)',
