'Jumia_Prices_Stock' => '가격 및 재고',
'Jumia_Push_Prices_Stock_Title' => 'Jumia로 가격 및 재고 전송',
'Jumia_Push_Prices_Stock_Desc' => 'Jumia 리스팅의 {sku}와 일치하는 SKU가 있는 모든 제품(및 옵션)의 현재 가격과 수량을 전송합니다. 업데이트는 Seller Center 피드로 제출되어 비동기로 적용됩니다. 피드 ID는 로그 탭에 기록되며, 품목별 거부 내역은 Seller Center의 피드 상태 화면에 표시됩니다.',
'Jumia_Push_Prices_Stock' => '가격 및 재고 전송',
'Jumia_Pull_Orders_Desc' => '마켓플레이스 주문을 판매로 가져오며({ref} 같은 참조 번호), Seller SKU로 제품과 매칭합니다. 이미 가져온 주문과 취소된 주문은 건너뛰므로 정기적으로 가져와도 안전합니다. 결제는 배송 완료된 주문에 대해서만 결제 완료로 표시됩니다(Jumia는 COD 위주).',
'Jumia_Guide_1' => 'Jumia {sellerCenter}에서 {menu}를 열고 API 키를 생성하세요.',
'Jumia_Guide_2' => '해당 국가의 API URL(예: 나이지리아는 {ng}, 케냐는 {ke}, 이집트는 {eg}), Seller Center 계정 이메일, 키를 입력한 다음 {test}를 실행하세요.',
'Jumia_Guide_3' => '각 Jumia 리스팅의 {sku}가 Stocky 제품 코드와 같은지 확인하세요. 이 값이 재고 전송과 주문 매칭 모두에 사용되는 식별자입니다.',
'Jumia_Guide_4' => '재고가 변경되면 가격 및 재고를 전송하고, 주문은 정기적으로 가져오세요(이 API에서는 Jumia 웹훅을 지원하지 않습니다).',
'Jumia_Guide_5' => '새 리스팅 생성은 Seller Center에서 하세요. Jumia는 카테고리별 속성과 이미지 검토를 요구하며, 이는 자체 포털에서만 제대로 처리됩니다.',
'Mailchimp_Hero_Title' => 'Mailchimp 오디언스 동기화',
