'Mailchimp_Double_Optin_Label' => '더블 옵트인 — 새 회원은 가입 전에 확인 이메일을 받습니다',
'Mailchimp_Double_Optin_Hint' => '(GDPR 준수를 위해 권장)',
'Mailchimp_Auto_Sync_Customers' => '새 고객이 생성될 때 자동 동기화',
'Mailchimp_With_Email' => '이메일 있음',
'Mailchimp_Push_Desc' => '이메일 주소가 있는 모든 고객을 선택한 오디언스에 추가하거나 업데이트합니다(이름과 전화번호 포함). 기존 회원의 구독 상태는 유지되며, 구독을 취소한 사람은 다시 구독되지 않습니다. 이메일이 없는 고객은 제외됩니다.',
'Mailchimp_Double_Optin_Off_Title' => '더블 옵트인이 꺼져 있습니다',
