'Mailchimp_Consent_Title' => '동의가 중요합니다',
'Mailchimp_Consent_Desc' => '마케팅에 동의하지 않은 사람에게 이메일을 보내면 GDPR/CAN-SPAM을 위반할 수 있으며 Mailchimp 계정이 정지될 수 있습니다. 더블 옵트인은 확인 절차를 Mailchimp에 맡기므로 안전한 기본값입니다.',
