'Shopify_G_Lead_Generic' => 'Shopify 스토어가 ERP와 동기화 상태를 유지하는 방법입니다. 위에서 스토어를 선택하면 해당 상태를 볼 수 있으며, 그대로 읽어도 됩니다. cron 줄과 웹훅 URL은 어떤 스토어를 연결하든 동일합니다.',
'Shopify_G_Ways_Note' => '대부분의 스토어는 두 가지를 모두 사용합니다. 첫 번째는 스토어를 분 단위로 최신 상태로 유지하고, 두 번째는 첫 번째가 놓친 것(도착하지 않은 웹훅, Shopify 관리자에서 직접 수정한 내용, 사이트가 다운된 밤 등)을 보완합니다.',
'Shopify_G_Both_Need' => '두 방식 모두 먼저 필요한 사항',
'Shopify_G_Credentials' => 'Shopify 자격 증명',
'Shopify_G_Cred_Intro' => '2026년 1월부터 Shopify는 관리자 화면에서 커스텀 앱을 더 이상 만들지 않으므로 연결 방식은 두 가지입니다:',
'Shopify_G_Cred_DevDash' => '{app}(현재 연결하는 모든 스토어) — {path}. 이 스토어가 동기화하는 항목에 필요한 Admin API 범위를 부여하고 스토어에 앱을 설치한 다음, 앱의 설정 페이지에서 {clientId}와 {clientSecret}을 {where}에 복사하세요. ERP가 이를 직접 액세스 토큰으로 교환하고 24시간마다 만료되기 전에 갱신합니다. 클라이언트 시크릿은 웹훅 서명에도 사용되므로 다른 것은 필요하지 않습니다. 앱과 스토어는 같은 Shopify 조직에 있어야 합니다.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard 앱',
'Shopify_G_Cred_Legacy' => '{app}(2026년 이전에 관리자에서 생성) — {token}({prefix})과 웹훅 서명 시크릿인 {secret}으로 변경 없이 계속 작동합니다. 토큰과는 다른 값이며, 둘을 바꿔 입력하는 것이 웹훅이 거부되는 흔한 원인입니다.',
'Shopify_G_Legacy_App' => '레거시 커스텀 앱',
'Shopify_G_API_Secret_Key' => 'API 시크릿 키',
'Shopify_G_Stored' => '저장됨',
'Shopify_G_Missing_Refused' => '없음 — 전송이 거부됩니다',
'Shopify_G_Where_Data_Desc' => '{path} 이 스토어가 판매하는 재고의 ERP 창고와, 해당 재고가 기록되는 Shopify 위치입니다. 이 값이 없으면 재고 동기화와 주문 가져오기 모두 실행되지 않습니다.',
'Shopify_G_Currently' => '현재: 창고 {warehouse}, 위치 {location}',
'Shopify_G_Not_Set_Lower' => '설정 안 됨',
'Shopify_G_Ready' => '준비됨',
'Shopify_G_Incomplete' => '미완료',
'Shopify_G_Manual_Syncs' => '수동으로 시작하는 동기화',
'Shopify_G_Manual_Desc' => '{centre}에서 시작한 동기화는 즉시 응답하고 백그라운드에서 짧은 구간 단위로 실행되며, 각 구간은 이전 구간이 멈춘 지점부터 이어집니다. 긴 웹 요청을 끊는 호스팅(LiteSpeed, nginx, 로드 밸런서)에서도 대용량 카탈로그가 중간에 끊기지 않으며, 페이지를 닫아도 중지되지 않습니다. 이를 위한 워커는 cron 한 줄만 추가하면 됩니다:',
'Shopify_G_Cron_Copied' => 'cron 줄이 복사되었습니다',
'Shopify_G_Manual_Note' => '워커가 없어도 동기화는 완료되지만, 동기화 센터 페이지가 열려 있는 동안에만 가능합니다. 몇 초 안에 실행을 처리하는 워커가 없으면 페이지가 한 번에 짧은 요청 하나씩 직접 진행합니다. Windows에서는 작업 스케줄러를 1분마다 실행하도록 설정하세요: 프로그램 {program}, 인수 {args}, 시작 위치 {dir}.',
'Shopify_G_Then_Pick' => '그다음 동기화 유지 방식을 선택하세요',
'Shopify_G_Right_Away' => '즉시',
'Shopify_G_Stock_Live' => '재고 실시간',
'Shopify_G_Stock_Not_Live' => '재고 실시간 아님',
'Shopify_G_Realtime_Lead' => '각 변경 사항이 발생하는 즉시 몇 초 안에 전송됩니다. 두 부분으로 나뉘며 각각 별도 스위치입니다. {webhooks}는 스토어의 이벤트를 가져오고, {push}는 재고를 내보냅니다.',
'Shopify_G_Webhooks_Lower' => '웹훅',
'Shopify_G_Instant_Push_Lower' => '즉시 재고 전송',
'Shopify_G_Webhooks_In' => '웹훅 — 스토어 → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify에서 발생한 주문, 주문 상태 변경, 제품·고객·재고 수정입니다. 스토어를 열고 {tab}에서 {button}을 누르세요. 두 번 눌러도 안전합니다. Shopify는 다음 주소로 전송합니다:',
'Shopify_G_Webhooks_Tab' => '웹훅 탭',
'Shopify_G_Webhooks_Note' => '이 주소는 인터넷에서 HTTPS로 접근할 수 있어야 합니다. Shopify는 {localhost}나 {test} 도메인으로는 전송하지 않습니다. 각 전송은 한 번만 기록되므로 Shopify의 재시도로 주문이 중복 생성되지 않으며, 실패한 전송은 재실행할 수 있습니다. 1단계의 서명 시크릿이 저장될 때까지 전송은 거부됩니다.',
'Shopify_G_Instant_Out' => '즉시 재고 전송 — ERP → 스토어',
'Shopify_G_Setting_Missed' => '많은 사람이 놓치는 설정입니다',
'Shopify_G_Pos_Not_Auto' => 'POS 판매는 자동으로 Shopify에 반영되지 {not}습니다. 꺼 두면 스토어는 다음 재고 전송 단계에서야 알게 되며, 그 사이에 계산대에서 이미 판매한 재고를 온라인에서 판매할 수 있습니다.',
'Shopify_G_Not' => '않',
'Shopify_G_Tick_Push' => '{where}에서 {setting}을 선택하세요. 설정은 이것으로 끝입니다. 워커도 cron도 필요 없습니다. 이후 모든 판매, 반품, 재고 조정은 판매가 저장된 직후 해당 제품만 전송하며, 20줄짜리 판매도 전송은 20번이 아니라 한 번입니다. 계산대는 이를 기다리지 않습니다.',
'Shopify_G_This_Store' => '이 스토어:',
'Shopify_G_Push_On' => '켬 — 변경 시 재고 전송',
'Shopify_G_Push_Off' => '끔 — 일정에 따라서만 재고 전송',
'Shopify_G_Push_Note' => '이미 Shopify 매핑이 있는 제품과 이 스토어 창고의 재고 변동만 전송됩니다. 제품 삭제, 창고 초기화 같은 일괄 작업은 이벤트 없이 재고를 기록하므로 예약된 재고 단계도 함께 유지하는 것이 좋습니다.',
'Shopify_G_Nothing_Install' => '추가로 설치할 것 없음',
'Shopify_G_No_Worker_Note' => '두 부분 모두 큐 워커나 cron 항목이 필요하지 않습니다. 들어오는 웹훅은 Shopify가 보낸 요청 안에서 처리되고, 나가는 재고 전송은 판매를 처리한 같은 프로세스에서 응답이 반환된 {after} 실행됩니다. 따라서 계산대는 Shopify를 기다리지 않으며, 응답하지 않는 스토어는 10초 후 포기하고 다음 예약 재고 전송에 맡깁니다.',
'Shopify_G_After' => '후에',
'Shopify_G_Artisan_Note' => '예외가 하나 있습니다. artisan 명령으로 변경된 재고는 응답이 없으므로 대신 {queue}에 대기열로 추가됩니다. 이것도 신속하게 전송하려면 해당 큐를 처리하세요:',
'Shopify_G_On_Schedule' => '일정에 따라',
'Shopify_G_On_Lower' => '켬',
'Shopify_G_Off_Lower' => '끔',
'Shopify_G_Scheduled_Lead' => '모든 항목을 주기적으로 양방향 재확인합니다. 실시간보다 느리지만, 즉시 전송을 사용하지 않는 스토어에 재고를 내보내고, 놓친 웹훅을 보완하며, 전체 카탈로그를 이동하는 유일한 방법입니다.',
'Shopify_G_Cron_Entry' => 'cron 항목',
'Shopify_G_Cron_Entry_Desc' => '이 항목이 없으면 예약된 작업은 실행되지 않습니다. 이 모듈 전용 한 줄이며, 예약해 둔 다른 작업 옆에 추가하세요:',
'Shopify_G_Cron_Note' => '가장 짧은 단계 간격이 5분이므로, 계획이 사용할 수 있는 최소 단위는 5분입니다. 더 긴 간격의 항목은 그대로 하한이 됩니다. 예를 들어 {example}이면 5분으로 설정한 단계는 15분마다 실행됩니다. Windows에서는 작업 스케줄러를 사용하세요: 프로그램 {program}, 인수 {args}, 시작 위치 {dir}.',
'Shopify_G_Switch_On_Plan' => '켜고 계획을 선택하세요',
'Shopify_G_Plan_Desc' => '{where} 스위치는 cron이 동작할지 여부를, 계획은 무엇을 할지를 결정합니다. {step}는 자체 간격을 가진 한 방향의 한 항목입니다 — {first}, {second}. 자체 칸을 비워 둔 단계에는 기본 간격이 사용됩니다.',
'Shopify_G_Step_Lower' => '단계',
'Shopify_G_Plan_Note' => '계획을 비워 두면 스토어는 기본 간격으로 주문을 가져오고 재고를 전송하며, 대부분의 스토어에 적합합니다. 주문은 가져오기만 가능합니다. 고객은 Shopify에서 주문하기 때문입니다.',
'Shopify_G_Schedule_On' => '일정 켬',
'Shopify_G_Schedule_Off' => '일정 끔 — 수동 전용',
'Shopify_G_When_Step_Runs' => '단계가 실제로 실행되는 시점',
'Shopify_G_When_Note' => '실행 기록상 같은 단계가 마지막으로 {started} 후 간격보다 오래 지났으면 실행 예정이 됩니다. 따라서 수동으로 시작한 동기화는 다음 자동 실행을 미루며, 계속 실패하는 단계는 매 주기가 아니라 간격마다 재시도됩니다. 스토어 개요에는 각 단계의 마지막 실행, 다음 예정 시간, 차단된 경우 그 이유가 표시됩니다. 일정에 넣기 전에 첫 카탈로그 전송은 먼저 {dryRun}으로 수동 실행하세요.',
'Shopify_G_Started_Lower' => '시작된',
'Shopify_G_Where_Setting' => '각 설정의 위치',
'Shopify_G_Where_Setting_Note' => '모두 기존 스토어에 있습니다: {path}에서 연필 아이콘(또는 스토어 페이지의 {edit})을 누르세요.',
'Shopify_G_Product_Images' => '제품 이미지',
'Shopify_G_Img_1' => '이미지는 {push} 시 제품과 함께 전송됩니다. 대표 이미지가 먼저, 그다음 갤러리, 그리고 자체 이미지가 있는 옵션마다 하나씩, 최대 50개까지 전송됩니다.',
'Shopify_G_Products_Push' => '제품 전송',
'Shopify_G_Img_2' => '옵션 이미지는 제품과 함께 업로드된 후 {assigned}됩니다. Shopify에서는 옵션이 제품 이미지 중 하나를 가리키는 방식이기 때문입니다. 대표 이미지를 재사용하는 옵션은 이미지를 두 번 업로드하지 않습니다.',
'Shopify_G_Assigned' => '해당 옵션에 지정',
'Shopify_G_Img_3' => '파일로 저장된 이미지는 링크가 아닌 Shopify로 {uploaded}되므로, 이 설치 환경이 인터넷에서 접근 불가능해도 작동합니다. 링크로 붙여넣은 이미지는 해당 URL로 Shopify에 전달되며, 이 URL은 공개적으로 접근 가능해야 합니다.',
'Shopify_G_Uploaded' => '업로드',
'Shopify_G_Img_4' => '이미지는 실제로 변경된 경우에만 다시 전송됩니다. 가격만 바꾸는 전송은 스토어의 이미지를 건드리지 않습니다. 이미지를 전송하면 전체 세트가 교체되기 때문입니다.',
'Shopify_G_Img_5' => 'ERP에서 이미지를 삭제해도 Shopify에서는 삭제되지 {not}습니다. Shopify에서도 삭제하지 않으면 스토어에 계속 표시됩니다.',
'Shopify_G_Commands' => '알아 두면 좋은 명령',
'Shopify_G_Command_Copied' => '명령이 복사되었습니다',
'Shopify_G_Foot' => '모든 동기화는 {logs}에 기록되며, 각 스토어 개요에는 각 단계의 마지막 실행, 다음 예정 시간, 무언가 차단 중일 때 그 원인이 표시됩니다. 동기화가 예상대로 동작하지 않았을 때 가장 먼저 확인할 곳입니다.',
'Shopify_G_Covers' => '적용 범위',
'Shopify_G_Covers_Rt' => 'Shopify에서 발생한 주문과 수정, ERP에서 나가는 재고(POS 판매, 반품, 재고 조정)',
'Shopify_G_Covers_Sch' => '카탈로그 전송과 빠른 경로가 놓친 모든 것을 포함한 양방향 전체',
'Shopify_G_Speed' => '속도',
