'StoreAdm_Eg' => '예: {example}',
'StoreAdm_Stock_Required_Available' => '{name}: 필요 {need} — 가용 {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash, SSLCommerz는 온라인 스토어 결제에서만 사용됩니다.',
'StoreAdm_PG_Intro_Desc' => 'Stripe 키는 전역으로 공유됩니다(관리자와 온라인 스토어가 같은 Stripe 연동을 사용). 각 탭은 온라인 스토어 결제에서 해당 결제 수단을 켜거나 끄며, 오프라인 결제에는 시스템 외부에서 결제하는 수단이 있습니다.',
'StoreAdm_PG_Used_By_Store_Only' => '온라인 스토어 결제에서만 사용',
