'StoreAdm_PG_Gw_Secret' => '{gw} 시크릿',
'StoreAdm_PG_Cards_Off' => '카드 결제가 꺼져 있습니다',
'StoreAdm_PG_Cards_Off_Desc' => '키는 유지됩니다. 다시 켤 때까지 온라인 스토어 결제에서 카드 옵션만 제공되지 않습니다.',
'StoreAdm_PG_No_Stripe_Key' => '저장된 Stripe 키 없음',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Stripe 키와 시크릿을 입력하면 온라인 스토어에서 카드 결제를 받을 수 있습니다.',
'StoreAdm_PG_Gw_Client_Id' => '{gw} 클라이언트 ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} 클라이언트 시크릿',
'StoreAdm_PG_Sandbox' => '샌드박스 (테스트 모드)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => '켜면 샌드박스 자격 증명으로 {sandbox}를 사용합니다. 끄면 {live}에서 실제 계정에 청구합니다.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} 웹훅 ID (선택 사항)',
'StoreAdm_PG_Paypal_Webhook_Hint' => '브라우저 리디렉션이 도착하지 않은 결제와 환불/지불 거절을 위한 보완 장치입니다. {site}에서 아래 URL을 가리키는 웹훅을 등록하고(이벤트: {events}) 웹훅 ID를 여기에 붙여넣으세요.',
'StoreAdm_PG_Webhook_Url' => '웹훅 URL:',
'StoreAdm_PG_Gw_Disabled' => '{gw}이(가) 비활성화되어 있습니다',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'PayPal을 켜고 REST 앱의 클라이언트 ID와 시크릿({site}에서 확인)을 입력하면 고객이 온라인 스토어 결제에서 PayPal로 결제할 수 있습니다.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} 공개 키',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} 시크릿 키',
'StoreAdm_PG_Paystack_Test_Live' => '테스트와 실거래는 키 쌍으로 결정됩니다. {test} 키는 테스트 모드로 실행되고, {live} 키는 실제 카드에 청구합니다. 별도의 샌드박스 스위치는 없습니다.',
'StoreAdm_PG_Paystack_Webhook_Url' => '웹훅 URL (선택적 보완 장치 — Paystack 대시보드의 Settings → API Keys & Webhooks에서 설정하세요. 요청은 시크릿 키로 HMAC 검증됩니다):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Paystack을 켜고 공개 키와 시크릿 키({site} → Settings → API Keys에서 확인)를 입력하면 온라인 스토어 결제에서 카드, 계좌 이체, 모바일 머니를 받을 수 있습니다.',
