'Cr_Guide_Step_Account_Help' => '택배사를 선택하고 해당 대시보드의 API 키를 붙여 넣으세요. 예를 들어 창고별로 하나씩, 여러 계정을 사용해도 됩니다.',
'Cr_Guide_Step_Test' => '연결 테스트',
'Cr_Guide_Step_Test_Help' => '연결 테스트는 키를 확인하며, 택배사 옵션에 필요한 코드를 함께 보여 주는 경우가 많습니다.',
'Cr_Guide_Step_Webhook' => 'Webhook URL 등록',
'Cr_Guide_Step_Webhook_Help' => '업데이트를 푸시하는 택배사는 상태가 즉시 변경되도록 계정 Webhook URL(아래 표시)이 필요합니다. 그 외 택배사는 일정에 따라 확인됩니다.',
'Cr_Guide_Step_Cod' => 'COD 정산금 입금 계좌 선택',
'Cr_Guide_Step_Cod_Help' => '택배사 설정에서 COD 정산금이 기록될 계좌와 반송된 소포 및 택배 요금 처리 방식을 선택하세요.',
'Cr_Guide_Step_Notify' => '고객에게 알리기',
'Cr_Guide_Step_Notify_Help' => '선택한 상태에서 배송 추적 페이지 링크와 함께 SMS, 이메일 또는 WhatsApp을 보냅니다.',
'Cr_Guide_Step_Book' => '첫 주문 예약',
'Cr_Guide_Step_Book_Help' => '판매 목록에서 판매 메뉴를 열고 택배사로 보내기를 선택하거나, 여러 판매를 선택하여 한 번에 보내세요.',
'Cr_Guide_Step_Errors' => '오류 주시하기',
'Cr_Guide_Step_Errors_Help' => '최근 24시간 동안 택배 오류가 없습니다.',
'Cr_Guide_Courier_Setup' => '택배사 설정',
'Cr_Guide_Pick_Courier' => '택배사를 선택하여 필요한 항목 확인',
'Cr_Guide_Add_This' => '이 택배사 추가',
'Cr_Guide_You_Need' => '필요한 항목',
'Cr_Guide_No_Keys' => 'API 키 없음: 연결할 항목이 없습니다.',
'Cr_Guide_Good_To_Know' => '알아 두면 좋은 정보',
'Cr_Guide_Webhooks' => 'Webhook 주소',
'Cr_Guide_How' => '등록 방법',
'Cr_Guide_How_It_Works' => '작동 방식',
'Cr_Guide_Meaning' => '의미',
'Cr_Guide_T_Statuses' => '상태',
'Cr_Guide_Statuses_Note' => '상태는 앞으로만 진행되므로 늦게 도착한 업데이트로 소포 상태가 되돌아가지 않습니다. 배달 완료된 소포도 반송 중 또는 반송됨으로 보고될 수 있습니다.',
'Cr_Guide_S_booked' => '택배사가 주문을 접수했지만 아직 집하되지 않았습니다. 예약은 이 단계에서만 취소할 수 있습니다.',
'Cr_Guide_S_picked_up' => '택배사가 소포를 집하했습니다.',
'Cr_Guide_S_in_transit' => '허브 간 이동 중, 통관 중 또는 보류 중입니다.',
'Cr_Guide_S_out_for_delivery' => '오늘 배달 기사가 배송 중입니다.',
'Cr_Guide_S_failed_attempt' => '부재, 수령 거부 또는 잘못된 주소입니다. 택배사가 다시 시도하거나 반송합니다.',
'Cr_Guide_S_delivered' => '고객에게 전달되었습니다. COD 금액은 택배사 수금 완료 상태가 됩니다.',
'Cr_Guide_S_returning' => '반송되어 돌아오는 중입니다.',
'Cr_Guide_S_returned' => '반송 완료: 검토할 반송에서 대기하거나 자동으로 재입고됩니다.',
'Cr_Guide_S_cancelled' => '예약이 취소되었습니다.',
'Cr_Guide_T_Booking' => '주문 예약',
'Cr_Guide_B_Booking' => '택배사로 보내기는 판매 정보로 양식을 채웁니다: 수령인, 주소, COD로 받을 미결제 잔액, 제품 무게. 자체 도시 목록이 있는 택배사는 선택기가 표시되며, 선택한 내용은 해당 도시에 대해 기억됩니다. 통합 배송 서비스, DHL, FedEx, UPS 및 Lalamove는 요금 비교를 제공합니다: 가격을 선택하고 예약을 누르면 구매됩니다. 판매 목록에서 여러 판매를 한 번에 예약할 수 있습니다.',
'Cr_Guide_T_Cod' => '착불 결제',
'Cr_Guide_B_Cod' => 'COD 소포는 미수금 → 택배사 수금 완료(배달 시) → 정산 완료 순으로 진행됩니다. 정산을 보고하는 택배사는 마지막 단계를 자동으로 처리하며, 그 외 택배사는 COD 업데이트를 사용하세요. 택배사 설정에서 계좌를 선택하면 정산금이 판매의 결제로 기록됩니다. 소포 처리가 완료되면 택배 요금을 경비로 저장할 수 있습니다.',
'Cr_Guide_T_Returns' => '반송된 소포',
'Cr_Guide_B_Returns' => '기본적으로 반송된 소포는 택배 배송의 검토할 반송에서 대기합니다. 재입고는 전체 주문에 대한 판매 반품을 생성하고 품목을 재고로 되돌립니다. 무시는 아무것도 되돌리지 않으며 파손되거나 분실된 소포에 사용합니다. 택배사 설정에서 자동 재입고로 변경할 수 있습니다.',
'Cr_Guide_T_Customers' => '고객 메시지 및 배송 추적 페이지',
'Cr_Guide_B_Customers' => '택배사 설정의 고객 알림은 선택한 상태에서 직접 작성한 문구로 SMS, 이메일 또는 WhatsApp을 소포당 한 번씩 보냅니다. 온라인 스토어의 배송 추적 페이지에서 고객은 운송장 번호 또는 주문 번호와 전화번호로 소포를 추적할 수 있습니다. 반송이 잦은 고객에게는 예약 시 반송 위험 배지가 표시됩니다.',
'Cr_Guide_T_Labels' => '라벨',
'Cr_Guide_B_Labels' => '라벨 인쇄는 택배사가 자체 라벨(PDF, 링크 또는 이미지)을 발급하면 해당 라벨을, 그렇지 않으면 운송장 바코드와 수금 금액이 포함된 Stocky 라벨을 제공합니다. 인쇄하려면 이 사이트의 팝업을 허용하세요. DHL, FedEx 및 UPS는 예약 시 한 번만 라벨을 제공하며, Stocky는 재인쇄를 위해 이를 보관합니다.',
'Cr_Guide_T_Faq' => '문제 해결',
'Cr_Guide_Q_Test' => '연결 테스트 실패',
'Cr_Guide_A_Test' => '테스트용 키는 테스트 모드에, 실운영 키는 실운영 모드에 사용하며 서로 다릅니다. 택배 로그를 열어 택배사 응답에서 정확한 원인을 확인하세요.',
'Cr_Guide_Q_City' => '택배사가 도시 또는 주소를 거부함',
'Cr_Guide_A_City' => '예약 양식의 택배사 도시 목록에서 도시를 선택하세요. 택배사는 자체 명칭만 허용합니다. 우편 주소를 사용하는 택배사는 주/도, 우편번호 및 두 글자 국가 코드도 필요합니다.',
'Cr_Guide_Q_Webhook' => '상태가 자동으로 변경되지 않음',
'Cr_Guide_A_Webhook' => '푸시 방식 택배사의 경우 택배사에 Webhook URL이 등록되어 있는지 확인하세요. 택배 로그에는 수신된 모든 업데이트와 거부된 사유(예: 잘못된 시크릿)가 표시됩니다. 그 외 택배사는 택배사 설정의 일정에 따라 확인되며, 지금 상태 확인을 누르면 즉시 조회합니다.',
'Cr_Guide_Q_Stuck' => '배송에 상태 확인 오류가 표시됨',
'Cr_Guide_A_Stuck' => '택배사가 최근 확인 요청을 거부했습니다. 사유는 배송 정보와 택배 로그에 표시됩니다. 실패가 반복되면 해당 배송은 더 이상 자동으로 확인되지 않습니다. 원인을 해결한 후 지금 상태 확인을 사용하세요.',
'Cr_Guide_Q_Label' => '라벨 인쇄 시 아무것도 열리지 않음',
'Cr_Guide_A_Label' => '브라우저가 팝업을 차단했습니다. 이 사이트의 팝업을 허용하고 다시 시도하세요.',
'Cr_Guide_Q_Cod' => 'COD 정산금이 판매에 기록되지 않음',
'Cr_Guide_A_Cod' => '택배사 설정에서 착불 결제 스위치를 켜고 계좌를 선택해야 합니다. 계좌가 없으면 정산은 정산 완료로 표시만 됩니다.',
