'Tfa_Guide_Trust_Text' => '"신뢰할 수 있는 기기 기억"은 로그인에 성공한 후 브라우저가 코드 입력을 건너뛸 수 있는 기간을 설정합니다. 매장 POS와 같은 공용 컴퓨터에는 "항상 코드 요청"을 선택하세요.',
'Tfa_Guide_Trust_Note' => '기간을 줄이면 이미 신뢰된 기기의 기간도 단축됩니다. 2FA를 끄거나 재설정하면 모든 기기가 해제됩니다.',
'Tfa_Guide_Lost_Title' => '휴대폰 분실 및 복구 코드 없음',
'Tfa_Guide_Lost_Text' => '사용자 페이지에서 2FA를 사용하는 사용자는 2FA 열에 "켜짐"으로 표시됩니다. 작업의 방패 버튼을 누르면 재설정됩니다: 사용자는 비밀번호만으로 로그인한 후 앱을 다시 설정합니다(필수인 경우 설정 요청을 받음).',
'Tfa_Guide_Lost_Warn' => '재설정하기 전에 요청자의 신원을 확인하세요 — 재설정하면 해당 계정의 2FA 보호가 해제됩니다.',
'Tfa_Guide_Open_Users' => '사용자 열기',
'Tfa_Guide_Mobile_Title' => '모바일 앱 및 API',
'Tfa_Guide_Mobile_Text' => '모바일 앱과 API 토큰 엔드포인트도 동일한 코드를 요청합니다. 2FA가 필수인데 아직 설정하지 않은 사용자는 먼저 웹에서 한 번 로그인하여 설정해야 합니다.',
'Tfa_Guide_Protect_Title' => '기본 보호 기능',
'Tfa_Guide_Protect_1' => '위의 잠금 설정과 관계없이 잘못된 코드를 5회 입력하면 해당 사용자의 코드 입력이 15분 동안 차단됩니다.',
'Tfa_Guide_Protect_2' => '각 코드와 각 복구 코드는 한 번만 사용할 수 있습니다.',
'Tfa_Guide_Protect_3' => '"로그인 활동 기록"이 켜져 있으면 잘못된 코드가 로그인 활동 목록에 "잘못된 2FA 코드"로 표시됩니다.',
'Tfa_Guide_Trouble_Title' => '문제 해결',
'Tfa_Guide_Faq_Clock_Q' => '새 코드인데도 “유효하지 않은 코드입니다”가 표시됨',
'Tfa_Guide_Faq_Clock_A' => '휴대폰 시계가 맞지 않을 가능성이 높습니다. 코드는 시간에 따라 생성되므로 휴대폰의 날짜와 시간을 자동(네트워크 시간)으로 설정한 후 다음 코드를 시도하세요.',
'Tfa_Guide_Faq_Phone_Q' => '새 휴대폰으로 이전',
'Tfa_Guide_Faq_Phone_A' => '인증 앱의 자체 이전 기능을 사용하거나, 프로필에서 2FA를 끈 후 새 휴대폰으로 다시 켜세요(필수인 경우 관리자에게 재설정을 요청하세요).',
'Tfa_Guide_Faq_Locked_Q' => '“잘못된 코드가 너무 많습니다”',
'Tfa_Guide_Faq_Locked_A' => '표시된 시간(최대 15분)만큼 기다리거나 관리자에게 해당 사용자의 2FA 재설정을 요청하세요.',
'Tfa_Guide_Faq_Key_Q' => '서버 이전 후 2FA 사용자가 아무도 로그인할 수 없음',
'Tfa_Guide_Faq_Key_A' => '2FA 시크릿은 .env 파일의 APP_KEY로 암호화됩니다. 앱을 이전하거나 복원할 때 동일한 APP_KEY를 유지하세요. 변경된 경우 2FA가 없는 관리자가 해당 사용자를 재설정해야 합니다.',
'Tfa_Guide_Button' => '가이드',
