'Tfa_Guide_Rollout_2' => '팀원에게 설치할 앱과 로그인 시 설정에 1분 정도 걸린다는 점을 알리세요.',
'Tfa_Guide_Rollout_3' => '"2단계 인증 필수"를 켜고 "필수 대상"을 비워 둔 다음(= 모든 사용자), 필요하면 유예 기간을 선택하세요. 제출을 클릭하세요.',
'Tfa_Guide_Rollout_4' => '"2FA 미사용 사용자 로그아웃"을 클릭하면 이미 로그인한 사용자가 나중이 아닌 지금 바로 설정하게 됩니다. 본인은 로그인 상태가 유지됩니다.',
'Tfa_Guide_Rollout_5' => '이 카드의 카운터나 사용자 페이지의 "설정 필요" 필터로 진행 상황을 확인하세요.',
'Tfa_Guide_Rollout_Note' => '유예 기간이 있으면 마감일까지 설정 화면에 “나중에 알림”이 표시되며, 마감일 이후에는 로그인하려면 설정이 필요합니다.',
'Tfa_Guide_Customers_Title' => '고객 계정(스토어 및 고객 포털)',
'Tfa_Guide_Customers_Text' => '고객도 자신의 계정을 보호할 수 있습니다. 각 고객에게 선택 사항이며 강제되지 않습니다: 스토어 설정 → 가입 접근 제어(온라인 스토어)와 고객 포털 → 포털 설정(고객 포털)에서 켜세요.',
'Tfa_Guide_Customers_1' => '고객은 내 계정(스토어) 또는 프로필(포털)에서 켭니다.',
'Tfa_Guide_Customers_2' => '이메일로 받는 코드(가장 간편하며 앱 불필요) 또는 복구 코드가 있는 인증 앱 중에서 선택합니다.',
'Tfa_Guide_Customers_3' => '이메일 코드를 사용하려면 메일 설정(설정 → 메일 설정)이 정상 작동해야 합니다. 코드는 10분 후 만료됩니다.',
'Tfa_Guide_Customers_4' => '나중에 이 옵션을 끄면 새 설정만 중단되며, 이미 사용 중인 고객은 계속 코드를 요청받고 직접 끌 수 있습니다.',
